  o.w("      (setq step (* newH spacingFactor))")
  o.w("      (setq i 0)")
  o.w("      (foreach ent ents")
  o.w("        (SL_SetTextEntityY ent (+ anchorY (* i step)))")
  o.w("        (setq i (+ i 1))")
  o.w("      )")
