  o.w("      (setq lo (vlax-safearray->list pmin))")
  o.w("      (setq hi (vlax-safearray->list pmax))")
  o.w("      (and (<= (car lo) (nth 2 bounds)) (>= (car hi) (nth 0 bounds)) (<= (cadr lo) (nth 3 bounds)) (>= (cadr hi) (nth 1 bounds)))")
  o.w("    )")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_ExpandBounds (bounds pad /)")
  o.w("  (if bounds (list (- (nth 0 bounds) pad) (- (nth 1 bounds) pad) (+ (nth 2 bounds) pad) (+ (nth 3 bounds) pad)) nil)")
  o.w(")")
  o.w("")
  o.w("(defun SL_SelectionByLayersInBounds (layers bounds / result layer src i ent)")
  o.w("  (setq result (ssadd))")
  o.w("  (if bounds")
  o.w("    (foreach layer layers")
  o.w("      (setq src (ssget \"_X\" (list (cons 8 layer))))")
  o.w("      (if src")
  o.w("        (progn")
  o.w("          (setq i 0)")
  o.w("          (while (< i (sslength src))")
  o.w("            (setq ent (ssname src i))")
  o.w("            (if (SL_EntityIntersectsBounds ent bounds) (ssadd ent result))")
  o.w("            (setq i (+ i 1))")
  o.w("          )")
  o.w("        )")
  o.w("      )")
  o.w("    )")
  o.w("  )")
  o.w("  result")
  o.w(")")
  o.w("")
  o.w("(defun SL_SelectionBounds (ss / i ent obj pmin pmax lo hi minX minY maxX maxY err)")
  o.w("  (vl-load-com)")
  o.w("  (if (and ss (> (sslength ss) 0))")
  o.w("    (progn")
  o.w("      (setq i 0 minX nil minY nil maxX nil maxY nil)")
  o.w("      (while (< i (sslength ss))")
  o.w("        (setq ent (ssname ss i))")
  o.w("        (setq obj (vlax-ename->vla-object ent))")
  o.w("        (setq err (vl-catch-all-apply 'vla-GetBoundingBox (list obj 'pmin 'pmax)))")
  o.w("        (if (not (vl-catch-all-error-p err))")
  o.w("          (progn")
  o.w("            (setq lo (vlax-safearray->list pmin))")
  o.w("            (setq hi (vlax-safearray->list pmax))")
  o.w("            (setq minX (if minX (min minX (car lo)) (car lo)))")
  o.w("            (setq minY (if minY (min minY (cadr lo)) (cadr lo)))")
  o.w("            (setq maxX (if maxX (max maxX (car hi)) (car hi)))")
  o.w("            (setq maxY (if maxY (max maxY (cadr hi)) (cadr hi)))")
  o.w("          )")
  o.w("        )")
  o.w("        (setq i (+ i 1))")
  o.w("      )")
  o.w("      (if minX (list minX minY maxX maxY) nil)")
  o.w("    )")
  o.w("    nil")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_SetTextEntityPoint (ent newP / data pair)")
  o.w("  (setq data (entget ent))")
  o.w("  (setq pair (if (assoc 11 data) (assoc 11 data) (assoc 10 data)))")
  o.w("  (if pair")
  o.w("    (progn")
  o.w("      (setq data (subst (cons (car pair) newP) pair data))")
  o.w("      (entmod data)")
  o.w("      (entupd ent)")
  o.w("    )")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_ScaleLegendLabelPositions (base factor / ss i ent p newP)")
  o.w("  (setq ss (ssget \"_X\" (list (cons 0 \"TEXT,MTEXT\") (cons 8 \"LEGEND_TEXT\"))))")
  o.w("  (if ss")
  o.w("    (progn")
  o.w("      (setq i 0)")
  o.w("      (while (< i (sslength ss))")
  o.w("        (setq ent (ssname ss i))")
  o.w("        (if (not (SL_IsLegendSummaryText ent))")
  o.w("          (progn")
  o.w("            (setq p (SL_TextEntityPoint ent))")
  o.w("            (if p")
  o.w("              (progn")
  o.w("                (setq newP (list (+ (car base) (* (- (car p) (car base)) factor)) (+ (cadr base) (* (- (cadr p) (cadr base)) factor)) (if (caddr p) (caddr p) 0.0)))")
  o.w("                (SL_SetTextEntityPoint ent newP)")
  o.w("              )")
  o.w("            )")
  o.w("          )")
  o.w("        )")
  o.w("        (setq i (+ i 1))")
  o.w("      )")
  o.w("    )")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_MoveLegendNonSummaryTextY (dy / ss i ent p)")
  o.w("  ;; Move LEGEND heading and AUT/MUT labels while leaving the four summary lines anchored.")
  o.w("  (setq ss (ssget \"_X\" (list (cons 0 \"TEXT,MTEXT\") (cons 8 \"LEGEND_TEXT\"))))")
  o.w("  (if (and ss (> (abs dy) 0.000001))")
  o.w("    (progn")
  o.w("      (setq i 0)")
  o.w("      (while (< i (sslength ss))")
  o.w("        (setq ent (ssname ss i))")
  o.w("        (if (not (SL_IsLegendSummaryText ent))")
  o.w("          (progn")
  o.w("            (setq p (SL_TextEntityPoint ent))")
  o.w("            (if p (SL_SetTextEntityPoint ent (list (car p) (+ (cadr p) dy) (if (caddr p) (caddr p) 0.0))))")
  o.w("          )")
  o.w("        )")
  o.w("        (setq i (+ i 1))")
  o.w("      )")
  o.w("    )")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_MoveSelectionY (ss dy / i ent)")
  o.w("  (if (and ss (> (abs dy) 0.000001))")
  o.w("    (progn")
  o.w("      (setq i 0)")
  o.w("      (while (< i (sslength ss))")
  o.w("        (setq ent (ssname ss i))")
  o.w("        (command \"_.MOVE\" ent \"\" (list 0.0 0.0 0.0) (list 0.0 dy 0.0))")
  o.w("        (setq i (+ i 1))")
  o.w("      )")
  o.w("    )")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_FirstTextHeight (layer / ss i data h value)")
  o.w("  ;; Return the smallest current height on the layer so mixed 2.0/2.3 legend text scales from the 2.0 body-text baseline.")
  o.w("  (setq ss (ssget \"_X\" (list (cons 0 \"TEXT,MTEXT\") (cons 8 layer))))")
  o.w("  (setq i 0 h nil)")
  o.w("  (if ss")
  o.w("    (while (< i (sslength ss))")
  o.w("      (setq data (entget (ssname ss i)))")
  o.w("      (setq value (cdr (assoc 40 data)))")
  o.w("      (if value (setq h (if h (min h value) value)))")
  o.w("      (setq i (+ i 1))")
  o.w("    )")
  o.w("  )")
  o.w("  h")
  o.w(")")
  o.w("")
  o.w("(defun SL_ReflowRightPanelForLegend (oldH newH / factor textSS textBounds localBounds geomSS geomBounds allLegendSS before after base delta upperSS summarySS summaryBounds summaryBeforeBounds sampleGroupSS sampleGroupBounds fixedGap desiredBottom moveY i ent)")
  o.w("  ;; The summary stack is the fixed bottom anchor. Samples and all upper panel content grow upward.")
  o.w("  (if (and oldH (> oldH 0.000001) newH (> newH 0.000001))")
  o.w("    (progn")
  o.w("      (setq factor (/ newH oldH))")
  o.w("      (setq textSS (SL_SelectionByLayers (list \"LEGEND_TEXT\")))")
  o.w("      (setq textBounds (SL_SelectionBounds textSS))")
  o.w("      (setq localBounds (SL_ExpandBounds textBounds (* oldH 2.5)))")
  o.w("      (setq geomSS (SL_SelectionByLayersInBounds (list \"LEGEND_SAMPLE\" \"LEGEND_AUT_HATCH\" \"LEGEND_MUT_HATCH\") localBounds))")
  o.w("      (setq allLegendSS (SL_SelectionByLayersInBounds (list \"LEGEND_SAMPLE\" \"LEGEND_AUT_HATCH\" \"LEGEND_MUT_HATCH\" \"LEGEND_TEXT\") localBounds))")
  o.w("      (setq geomBounds (SL_SelectionBounds geomSS))")
  o.w("      (setq before (SL_SelectionBounds allLegendSS))")
  o.w("      ;; Use a deliberate fixed clearance from the top of Total Scans to the bottom of the AUT/MUT boxes.")
  o.w("      (setq summarySS (ssadd))")
  o.w("      (setq i 0)")
  o.w("      (if textSS")
  o.w("        (while (< i (sslength textSS))")
  o.w("          (setq ent (ssname textSS i))")
  o.w("          (if (SL_IsLegendSummaryText ent) (ssadd ent summarySS))")
  o.w("          (setq i (+ i 1))")
  o.w("        )")
  o.w("      )")
  o.w("      (setq summaryBeforeBounds (SL_SelectionBounds summarySS))")
  o.w("      (setq fixedGap 3.0)")
  o.w("      ;; Keep Overlay (the lowest summary line) fixed and re-space the other summary lines upward.")
  o.w("      (SL_ReflowTextStack \"LEGEND_TEXT\" newH 1.55 T)")
  o.w("      (if (and before geomBounds geomSS (> (sslength geomSS) 0))")
  o.w("        (progn")
  o.w("          ;; Scale the AUT/MUT sample geometry from its bottom-left corner.")
  o.w("          (setq base (list (nth 0 geomBounds) (nth 1 geomBounds) 0.0))")
  o.w("          (command \"_.SCALE\" geomSS \"\" base factor)")
  o.w("          (SL_ScaleLegendLabelPositions base factor)")
  o.w("        )")
  o.w("      )")
  o.w("      ;; Position the sample group from its true lowest visible point.")
  o.w("      ;; This includes the AUT/MUT captions, which extend below the sample boxes.")
  o.w("      (setq summaryBounds (SL_SelectionBounds summarySS))")
  o.w("      (setq sampleGroupSS (ssadd))")
  o.w("      (setq i 0)")
  o.w("      (if geomSS")
  o.w("        (while (< i (sslength geomSS))")
  o.w("          (ssadd (ssname geomSS i) sampleGroupSS)")
  o.w("          (setq i (+ i 1))")
  o.w("        )")
  o.w("      )")
  o.w("      (setq i 0)")
  o.w("      (if textSS")
  o.w("        (while (< i (sslength textSS))")
  o.w("          (setq ent (ssname textSS i))")
  o.w("          (if (not (SL_IsLegendSummaryText ent)) (ssadd ent sampleGroupSS))")
  o.w("          (setq i (+ i 1))")
  o.w("        )")
  o.w("      )")
  o.w("      (setq sampleGroupBounds (SL_SelectionBounds sampleGroupSS))")
  o.w("      (if (and summaryBounds sampleGroupBounds)")
  o.w("        (progn")
  o.w("          (setq desiredBottom (+ (nth 3 summaryBounds) fixedGap))")
  o.w("          (setq moveY (- desiredBottom (nth 1 sampleGroupBounds)))")
  o.w("          (SL_MoveSelectionY geomSS moveY)")
  o.w("          (SL_MoveLegendNonSummaryTextY moveY)")
  o.w("        )")
  o.w("      )")
  o.w("      (setq textSS (SL_SelectionByLayers (list \"LEGEND_TEXT\")))")
  o.w("      (setq textBounds (SL_SelectionBounds textSS))")
  o.w("      (setq localBounds (SL_ExpandBounds textBounds (* newH 2.5)))")
  o.w("      (setq allLegendSS (SL_SelectionByLayersInBounds (list \"LEGEND_SAMPLE\" \"LEGEND_AUT_HATCH\" \"LEGEND_MUT_HATCH\" \"LEGEND_TEXT\") localBounds))")
  o.w("      (setq after (SL_SelectionBounds allLegendSS))")
  o.w("      (setq delta (if (and before after) (- (nth 3 after) (nth 3 before)) 0.0))")
  o.w("      (if (> (abs delta) 0.000001)")
  o.w("        (progn")
  o.w("          (setq upperSS (SL_SelectionByLayers (list \"HEADS\" \"HEAD_NOZZLE_TEXT\" \"HEAD_MUT_TEXT\" \"HEAD_TITLE_TEXT\" \"HEAD_CLOCK_TEXT\" \"TITLE_BLOCK\" \"TITLE_BLOCK_TEXT\")))")
  o.w("          (SL_MoveSelectionY upperSS delta)")
  o.w("        )")
  o.w("      )")
  o.w("      delta")
  o.w("    )")
  o.w("    0.0")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_TextLayerHeight (layer / ss ent data h mixed i h2)")
  o.w("  (setq ss (ssget \"_X\" (list (cons 0 \"TEXT,MTEXT\") (cons 8 layer))))")
  o.w("  (if (and ss (> (sslength ss) 0))")
  o.w("    (progn")
  o.w("      (setq i 0 h nil mixed nil)")
  o.w("      (while (< i (sslength ss))")
  o.w("        (setq ent (ssname ss i))")
  o.w("        (setq data (entget ent))")
  o.w("        (setq h2 (cdr (assoc 40 data)))")
  o.w("        (if h2")
  o.w("          (if (null h)")
  o.w("            (setq h h2)")
  o.w("            (if (> (abs (- h h2)) 0.000001) (setq mixed T))")
  o.w("          )")
  o.w("        )")
  o.w("        (setq i (+ i 1))")
  o.w("      )")
  o.w("      (cond")
  o.w("        (mixed \"Mixed\")")
  o.w("        (h (rtos h 2 3))")
  o.w("        (T \"--\")")
  o.w("      )")
  o.w("    )")
  o.w("    \"--\"")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_MenuLine (num label layer)")
  o.w("  (princ (strcat \"\\n \" (if (< num 10) \" \" \"\") (itoa num) \"  \" label \"  [\" (SL_TextLayerHeight layer) \"]\"))")
  o.w(")")
  o.w("")
  o.w("(defun SL_TextSizeMenu ()")
  o.w("  (princ \"\\n========================================\")")
  o.w("  (princ \"\\n         SCAN GENERATOR TEXT RESIZE\")")
  o.w("  (princ \"\\n========================================\")")
  o.w("  (princ \"\\nCurrent heights are shown in brackets.\")")
  o.w("  (SL_MenuLine 1  \"Scan IDs....................\" \"SCAN_TEXT\")")
  o.w("  (SL_MenuLine 2  \"Support / Object IDs........\" \"SUPPORT_TEXT\")")
  o.w("  (SL_MenuLine 3  \"Shell Nozzle IDs............\" \"SHELL_NOZZLE_TEXT\")")
  o.w("  (SL_MenuLine 4  \"Head Nozzle IDs.............\" \"HEAD_NOZZLE_TEXT\")")
  o.w("  (SL_MenuLine 5  \"Shell MUT IDs...............\" \"SHELL_MUT_TEXT\")")
  o.w("  (SL_MenuLine 6  \"Head MUT IDs................\" \"HEAD_MUT_TEXT\")")
  o.w("  (SL_MenuLine 7  \"X-Axis ruler text...........\" \"X_RULER_TEXT\")")
  o.w("  (SL_MenuLine 8  \"Y-Axis ruler text...........\" \"Y_RULER_TEXT\")")
  o.w("  (SL_MenuLine 9  \"Legend / summary............\" \"LEGEND_TEXT\")")
  o.w("  (SL_MenuLine 10 \"Circ weld labels............\" \"CIRC_WELD_TEXT\")")
  o.w("  (SL_MenuLine 11 \"Long seam labels............\" \"LONG_SEAM_TEXT\")")
  o.w("  (SL_MenuLine 12 \"Title block text............\" \"TITLE_BLOCK_TEXT\")")
  o.w("  (SL_MenuLine 13 \"Head titles.................\" \"HEAD_TITLE_TEXT\")")
  o.w("  (SL_MenuLine 14 \"Head clock text.............\" \"HEAD_CLOCK_TEXT\")")
  o.w("  (princ \"\\n 15  All generated text\")")
  o.w("  (princ \"\\n 16  Select individual text objects\")")
  o.w("  (princ \"\\n  0  Exit\")")
  o.w(")")
  o.w("")
  o.w("(defun c:TEXTRESIZE ( / choice newH oldLegendH layer layers ss count item done)")
  o.w("  (setq done nil)")
  o.w("  (while (not done)")
  o.w("    (SL_TextSizeMenu)")
  o.w("    (initget 4)")
  o.w("    (setq choice (getint \"\\nEnter option number <0>: \"))")
  o.w("    (if (null choice) (setq choice 0))")
  o.w("    (cond")
  o.w("      ((= choice 0)")
  o.w("        (setq done T)")
  o.w("        (princ \"\\nTEXTRESIZE finished.\")")
  o.w("      )")
  o.w("      ((and (>= choice 1) (<= choice 16))")
  o.w("        (initget 7)")
  o.w("        (setq newH (getreal \"\\nEnter new text height: \"))")
  o.w("        (setq oldLegendH (if (or (= choice 9) (= choice 15)) (SL_FirstTextHeight \"LEGEND_TEXT\") nil))")
  o.w("        (if newH")
  o.w("          (progn")
  o.w("            (setq layer (cond")
  o.w("              ((= choice 1) \"SCAN_TEXT\")")
  o.w("              ((= choice 2) \"SUPPORT_TEXT\")")
  o.w("              ((= choice 3) \"SHELL_NOZZLE_TEXT\")")
  o.w("              ((= choice 4) \"HEAD_NOZZLE_TEXT\")")
  o.w("              ((= choice 5) \"SHELL_MUT_TEXT\")")
  o.w("              ((= choice 6) \"HEAD_MUT_TEXT\")")
  o.w("              ((= choice 7) \"X_RULER_TEXT\")")
  o.w("              ((= choice 8) \"Y_RULER_TEXT\")")
  o.w("              ((= choice 9) \"LEGEND_TEXT\")")
  o.w("              ((= choice 10) \"CIRC_WELD_TEXT\")")
  o.w("              ((= choice 11) \"LONG_SEAM_TEXT\")")
  o.w("              ((= choice 12) \"TITLE_BLOCK_TEXT\")")
  o.w("              ((= choice 13) \"HEAD_TITLE_TEXT\")")
  o.w("              ((= choice 14) \"HEAD_CLOCK_TEXT\")")
  o.w("              (T \"\")")
  o.w("            ))")
  o.w("            (cond")
  o.w("              ((<= choice 14)")
  o.w("                (setq count (SL_ResizeTextLayer layer newH))")
  o.w("              )")
  o.w("              ((= choice 15)")
  o.w("                (setq layers (list \"SCAN_TEXT\" \"SUPPORT_TEXT\" \"SHELL_NOZZLE_TEXT\" \"HEAD_NOZZLE_TEXT\" \"SHELL_MUT_TEXT\" \"HEAD_MUT_TEXT\" \"X_RULER_TEXT\" \"Y_RULER_TEXT\" \"LEGEND_TEXT\" \"CIRC_WELD_TEXT\" \"LONG_SEAM_TEXT\" \"TITLE_BLOCK_TEXT\" \"HEAD_TITLE_TEXT\" \"HEAD_CLOCK_TEXT\"))")
  o.w("                (setq count 0)")
  o.w("                (foreach item layers (setq count (+ count (SL_ResizeTextLayer item newH))))")
  o.w("              )")
  o.w("              ((= choice 16)")
  o.w("                (princ \"\\nSelect TEXT or MTEXT objects: \")")
  o.w("                (setq ss (ssget (list (cons 0 \"TEXT,MTEXT\"))))")
  o.w("                (setq count (if ss (sslength ss) 0))")
  o.w("                (SL_SetTextHeightInSelection ss newH)")
  o.w("              )")
  o.w("            )")
  o.w("            ;; Rebuild the right panel from the fixed legend bottom anchor.")
  o.w("            ;; Legend samples scale with the text, summary lines reflow, and the heads/title move by measured added height.")
  o.w("            (if (or (= choice 9) (= choice 15)) (SL_ReflowRightPanelForLegend oldLegendH newH))")
  o.w("            (if (or (= choice 12) (= choice 15)) (SL_ReflowTextStack \"TITLE_BLOCK_TEXT\" newH 1.75 nil))")
  o.w("            (command \"_.REGEN\")")
  o.w("            (princ (strcat \"\\nUpdated \" (itoa count) \" text object(s) to height \" (rtos newH 2 3) \".\"))")
  o.w("            (princ \"\\nChoose another category, or enter 0 to exit.\")")
  o.w("          )")
  o.w("        )")
  o.w("      )")
  o.w("      (T (princ \"\\nInvalid option. Enter a number from 0 through 16.\"))")
  o.w("    )")
  o.w("  )")
  o.w("  (princ)")
  o.w(")")
  o.w("")
  o.w(";; ------------------------------------------------------------")
  o.w(";; NOZZLEWRAP - automatically wrap all shell nozzles centered on opposite rollout boundaries.")
  o.w(";; Click directly on the two opposite vessel rectangle edges used for circumference wrapping.")
  o.w(";; All CIRCLE entities on the NOZZLES layer whose centers fall on either boundary are processed.")
  o.w(";; Also supports left/right boundaries when the rollout is rotated.")
  o.w(";; ------------------------------------------------------------")
  o.w("(defun SL_ArcFromCircle (cdata ctr rad a1 a2 / ed item code)")
  o.w("  (setq ed (list (cons 0 \"ARC\") (cons 8 (cdr (assoc 8 cdata))) (cons 10 ctr) (cons 40 rad) (cons 50 a1) (cons 51 a2)))")
  o.w("  (foreach code (list 6 48 62 370 420)")
  o.w("    (setq item (assoc code cdata))")
  o.w("    (if item (setq ed (append ed (list item))))")
  o.w("  )")
  o.w("  (entmakex ed)")
  o.w(")")
  o.w("")
  o.w("(defun SL_WrapCircleAtEdges (ent cdata ctr rad horizontal edge1 edge2 / src dst c1 c2 a1 a2 b1 b2 z)")
  o.w("  (setq z (if (caddr ctr) (caddr ctr) 0.0))")
  o.w("  (if horizontal")
  o.w("    (progn")
  o.w("      (if (<= (abs (- (cadr ctr) edge1)) (abs (- (cadr ctr) edge2)))")
  o.w("        (setq src edge1 dst edge2)")
  o.w("        (setq src edge2 dst edge1)")
  o.w("      )")
  o.w("      (setq c1 (list (car ctr) src z) c2 (list (car ctr) dst z))")
  o.w("      (if (< dst src)")
  o.w("        (setq a1 pi a2 (* 2.0 pi) b1 0.0 b2 pi)")
  o.w("        (setq a1 0.0 a2 pi b1 pi b2 (* 2.0 pi))")
  o.w("      )")
  o.w("    )")
  o.w("    (progn")
  o.w("      (if (<= (abs (- (car ctr) edge1)) (abs (- (car ctr) edge2)))")
  o.w("        (setq src edge1 dst edge2)")
  o.w("        (setq src edge2 dst edge1)")
  o.w("      )")
  o.w("      (setq c1 (list src (cadr ctr) z) c2 (list dst (cadr ctr) z))")
  o.w("      (if (> dst src)")
  o.w("        (setq a1 (- (/ pi 2.0)) a2 (/ pi 2.0) b1 (/ pi 2.0) b2 (* 1.5 pi))")
  o.w("        (setq a1 (/ pi 2.0) a2 (* 1.5 pi) b1 (- (/ pi 2.0)) b2 (/ pi 2.0))")
  o.w("      )")
  o.w("    )")
  o.w("  )")
  o.w("  (entdel ent)")
  o.w("  (SL_ArcFromCircle cdata c1 rad a1 a2)")
  o.w("  (SL_ArcFromCircle cdata c2 rad b1 b2)")
  o.w("  T")
  o.w(")")
  o.w("")
  o.w("(defun c:NOZZLEWRAP ( / *error* oldOsmode p1 p2 dx dy horizontal edge1 edge2 tol ss i ent cdata ctr rad coord count)")
  o.w("  ;; Temporarily add Nearest object snap (OSMODE bit 512), preserving every existing snap mode.")
  o.w("  (setq oldOsmode (getvar \"OSMODE\"))")
  o.w("  (defun *error* (msg)")
  o.w("    (setvar \"OSMODE\" oldOsmode)")
  o.w("    (if (and msg (/= msg \"Function cancelled\") (/= msg \"quit / exit abort\"))")
  o.w("      (princ (strcat \"\\nNOZZLEWRAP error: \" msg))")
  o.w("    )")
  o.w("    (princ)")
  o.w("  )")
  o.w("  (setvar \"OSMODE\" (logior oldOsmode 512))")
  o.w("  (setq tol 0.01)")
  o.w("  (setq p1 (getpoint \"\\nFIRST EDGE: Click the vessel rectangle TOP long edge. If the rollout is rotated, click the LEFT long edge: \"))")
  o.w("  (if p1 (setq p2 (getpoint \"\\nSECOND EDGE: Click the OPPOSITE vessel rectangle BOTTOM long edge. If rotated, click the RIGHT long edge: \")))")
  o.w("  (cond")
  o.w("    ((or (null p1) (null p2)) (princ \"\\nNOZZLEWRAP cancelled.\"))")
  o.w("    (T")
  o.w("      (setq dx (abs (- (car p2) (car p1))) dy (abs (- (cadr p2) (cadr p1))))")
  o.w("      (if (and (< dx 0.000001) (< dy 0.000001))")
  o.w("        (princ \"\\nThe two boundary points are too close together.\")")
  o.w("        (progn")
  o.w("          (setq horizontal (> dy dx))")
  o.w("          (if horizontal")
  o.w("            (setq edge1 (cadr p1) edge2 (cadr p2))")
  o.w("            (setq edge1 (car p1) edge2 (car p2))")
  o.w("          )")
  o.w("          (setq ss (ssget \"_X\" (list (cons 0 \"CIRCLE\") (cons 8 \"NOZZLES\"))))")
  o.w("          (setq count 0 i 0)")
  o.w("          (command \"_.UNDO\" \"_Begin\")")
  o.w("          (if ss")
  o.w("            (repeat (sslength ss)")
  o.w("              (setq ent (ssname ss i) i (1+ i) cdata (entget ent))")
  o.w("              (setq ctr (cdr (assoc 10 cdata)) rad (cdr (assoc 40 cdata)))")
  o.w("              (setq coord (if horizontal (cadr ctr) (car ctr)))")
  o.w("              (if (or (<= (abs (- coord edge1)) tol) (<= (abs (- coord edge2)) tol))")
  o.w("                (progn")
  o.w("                  (SL_WrapCircleAtEdges ent cdata ctr rad horizontal edge1 edge2)")
  o.w("                  (setq count (1+ count))")
  o.w("                )")
  o.w("              )")
  o.w("            )")
  o.w("          )")
  o.w("          (command \"_.UNDO\" \"_End\")")
  o.w("          (command \"_.REGEN\")")
  o.w("          (if (> count 0)")
  o.w("            (princ (strcat \"\\nNOZZLEWRAP complete. \" (itoa count) \" nozzle(s) wrapped.\"))")
  o.w("            (princ \"\\nNo nozzle centers were found on the selected boundaries.\")")
  o.w("          )")
  o.w("        )")
  o.w("      )")
  o.w("    )")
  o.w("  )")
  o.w("  (setvar \"OSMODE\" oldOsmode)")
  o.w("  (princ)")
  o.w(")")
  o.w("")
  o.w(";; ------------------------------------------------------------")
  WriteObjectWrapLisp(o)
  WriteSectionViewportLisp(o)
  o.w(";; AXISBUILDER - master launcher for AxisBuilder commands.")
  o.w(";; ------------------------------------------------------------")
  o.w("(defun SL_ScanMenuDisplay ()")
  o.w("  (princ \"\\n========================================\")")
  o.w("  (princ \"\\n              AXISBUILDER\")")
  o.w("  (princ \"\\n========================================\")")
  o.w("  (princ \"\\n  1  Generate Scan Layout\")")
  o.w("  (princ \"\\n  2  Resize Generated Text\")")
  o.w("  (princ \"\\n  3  Wrap Shell Nozzle\")")
  o.w("  (princ \"\\n  4  Wrap Support/Object\")")
  o.w("  (princ \"\\n  5  Create Letter-Size Section Sheets\")")
  o.w("  (princ \"\\n  0  Exit\")")
  o.w(")")
  o.w("")
  o.w("(defun SL_RunMenuCommand (fn label / result)")
  o.w("  ;; Trap command cancellation/errors so control returns to AXISBUILDER.")
  o.w("  (setq result (vl-catch-all-apply fn nil))")
  o.w("  (if (vl-catch-all-error-p result)")
  o.w("    (princ (strcat \"\\n\" label \" stopped: \" (vl-catch-all-error-message result)))")
  o.w("  )")
  o.w("  (princ)")
  o.w(")")
  o.w("")
  o.w("(defun c:AXISBUILDER ( / choice done)")
  o.w("  (setq done nil)")
  o.w("  (while (not done)")
  o.w("    (SL_ScanMenuDisplay)")
  o.w("    (initget 4)")
  o.w("    (setq choice (getint \"\\nSelect an option [0-5] <0>: \"))")
  o.w("    (if (null choice) (setq choice 0))")
  o.w("    (cond")
  o.w("      ((= choice 0) (setq done T))")
  o.w("      ((= choice 1) (SL_RunMenuCommand 'c:SCANLAYOUT \"SCANLAYOUT\"))")
  o.w("      ((= choice 2) (SL_RunMenuCommand 'c:TEXTRESIZE \"TEXTRESIZE\"))")
  o.w("      ((= choice 3) (SL_RunMenuCommand 'c:NOZZLEWRAP \"NOZZLEWRAP\"))")
  o.w("      ((= choice 4) (SL_RunMenuCommand 'c:OBJECTWRAP \"OBJECTWRAP\"))")
  o.w("      ((= choice 5) (SL_RunMenuCommand 'c:SECTIONPAGES \"SECTIONPAGES\"))")
  o.w("      (T (princ \"\\nInvalid option. Enter 0, 1, 2, 3, 4, or 5.\"))")
  o.w("    )")
  o.w("  )")
  o.w("  (princ \"\\nAXISBUILDER closed.\")")
  o.w("  (princ)")
  o.w(")")
  o.w("")
  o.w(";; Backward-compatible alias for existing workflows.")
  o.w("(defun c:SCANMENU () (c:AXISBUILDER))")
  o.w("")
  o.w("(defun SL_HatchRect (x y w h layer / k x1 y1 x2 y2 step)")
  o.w("  ;; Custom 45-degree line hatch. More reliable than interactive HATCH in scripts.")
  o.w("  (setq step SL_HATCH_SPACING)")
  o.w("  (if (<= step 0.0) (setq step 2.5))")
  o.w("  (setq k (- h))")
  o.w("  (while (<= k w)")
  o.w("    (setq x1 (max 0.0 k))")
  o.w("    (setq y1 (- x1 k))")
  o.w("    (setq x2 (min w (+ h k)))")
  o.w("    (setq y2 (- x2 k))")
  o.w("    (if (> x2 x1)")
  o.w("      (SL_Line (+ x x1) (+ y y1) (+ x x2) (+ y y2) layer)")
  o.w("    )")
  o.w("    (setq k (+ k step))")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_FitTextHeight (w h txt / longSide shortSide byShort byLong th)")
  o.w("  ;; Smart text sizing: conservative sizing so labels stay inside scan boxes.")
  o.w("  (setq longSide (max w h))")
  o.w("  (setq shortSide (min w h))")
  o.w("  ;; Limit by short side first, then reduce more for longer labels.")
  o.w("  (setq byShort (* shortSide 0.22))")
  o.w("  (setq byLong (/ (* longSide 0.78) (* (max 1 (strlen txt)) 0.85)))")
  o.w("  (setq th (min byShort byLong))")
  o.w("  (if (< th 0.45) (setq th 0.45))")
  o.w("  th")
  o.w(")")
  o.w("")
  o.w("(defun SL_LabelRect (x y w h txt outlineLayer hatchLayer / cx cy rot th)")
  o.w("  (setq cx (+ x (/ w 2.0)))")
  o.w("  (setq cy (+ y (/ h 2.0)))")
  o.w("  (setq rot (if (> h w) 90 0))")
  o.w("  (setq th (SL_FitTextHeight w h txt))")
  o.w("  (SL_Rect x y w h outlineLayer)")
  o.w("  (if (and (/= hatchLayer \"\") (= SL_HATCH_ENABLED \"YES\"))")
  o.w("    (SL_HatchRect x y w h hatchLayer)")
  o.w("  )")
  o.w("  (SL_Text cx cy th rot txt outlineLayer)")
  o.w(")")
  o.w("")
  o.w("(defun SL_MUTPoint (x y txt / lr)")
  o.w("  ;; Shell manual UT location: MUT ID text only at the recorded X/Y point.")
  o.w("  (setq lr (SL_ReadableRot))")
  o.w("  (SL_Text x y 1.5 lr txt \"SHELL_MUT_TEXT\")")
  o.w(")")
  o.w("")
  o.w("(defun SL_AddAvoidRect (x y w h)")
  o.w("  (setq SL_AVOID_RECTS (cons (list x y (+ x w) (+ y h)) SL_AVOID_RECTS))")
  o.w(")")
  o.w("")
  o.w("(defun SL_BBox (cx cy tw th rot / hw hh)")
  o.w("  ;; Approximate text bounding box in logical drawing coordinates.")
  o.w("  (if (= (abs rot) 90)")
  o.w("    (progn (setq hw (/ th 2.0)) (setq hh (/ tw 2.0)))")
  o.w("    (progn (setq hw (/ tw 2.0)) (setq hh (/ th 2.0)))")
  o.w("  )")
  o.w("  (list (- cx hw) (- cy hh) (+ cx hw) (+ cy hh))")
  o.w(")")
  o.w("")
  o.w("(defun SL_Overlap (a b)")
  o.w("  (not (or (<= (nth 2 a) (nth 0 b)) (>= (nth 0 a) (nth 2 b)) (<= (nth 3 a) (nth 1 b)) (>= (nth 1 a) (nth 3 b))))")
  o.w(")")
  o.w("")
  o.w("(defun SL_ClearBBox (bb / ok r)")
  o.w("  ;; Keep label inside vessel and outside registered objects.")
  o.w("  (setq ok T)")
  o.w("  (if (or (< (nth 0 bb) 0.0) (< (nth 1 bb) 0.0) (> (nth 2 bb) SL_VESSEL_XLEN) (> (nth 3 bb) SL_VESSEL_YLEN)) (setq ok nil))")
  o.w("  (foreach r SL_AVOID_RECTS (if (SL_Overlap bb r) (setq ok nil)))")
  o.w("  ok")
  o.w(")")
  o.w("")
  o.w("(defun SL_CircleSmart (x y dia txt mode layer / r th lr tw insideOK outsideNeeded candidates cand lx ly bb found leaderStartX leaderStartY)")
  o.w("  (setq r (/ dia 2.0))")
  o.w("  (setq mode (strcase mode))")
  o.w("  (if (= mode \"\") (setq mode \"AUTO\"))")
  o.w("  (SL_SetLayer layer)")
  o.w("  (command \"CIRCLE\" (SL_pt (SL_tf_x x y) (SL_tf_y x y)) (rtos r 2 3))")
  o.w("  (setq lr (SL_ReadableRot))")
  o.w("  (setq th (max 1.6 (min 2.4 (* dia 0.22))))")
  o.w("  (setq tw (* (max 1 (strlen txt)) th 0.60))")
  o.w("  (setq insideOK (and (>= dia SL_MIN_NOZZLE_DIA) (< tw (* dia 0.75))))")
  o.w("  (setq outsideNeeded (or (= mode \"OUTSIDE\") (and (= mode \"AUTO\") (not insideOK)) (= SL_SMART_NOZZLES \"NO\")))")
  o.w("  (if (= mode \"INSIDE\") (setq outsideNeeded nil))")
  o.w("  (if (and (/= txt \"\") (not outsideNeeded))")
  o.w("    (SL_Text x y th lr txt layer)")
  o.w("    (if (/= txt \"\")")
  o.w("      (progn")
  o.w("        ;; Try positions: right, upper-right, lower-right, left, upper-left, lower-left, above, below.")
  o.w("        (setq candidates (list")
  o.w("          (list (+ x r SL_NOZZLE_LEADER_LEN (/ tw 2.0)) y (+ x r) y)")
  o.w("          (list (+ x r SL_NOZZLE_LEADER_LEN (/ tw 2.0)) (+ y r SL_NOZZLE_LEADER_LEN) (+ x r) (+ y r))")
  o.w("          (list (+ x r SL_NOZZLE_LEADER_LEN (/ tw 2.0)) (- y r SL_NOZZLE_LEADER_LEN) (+ x r) (- y r))")
  o.w("          (list (- x r SL_NOZZLE_LEADER_LEN (/ tw 2.0)) y (- x r) y)")
  o.w("          (list (- x r SL_NOZZLE_LEADER_LEN (/ tw 2.0)) (+ y r SL_NOZZLE_LEADER_LEN) (- x r) (+ y r))")
  o.w("          (list (- x r SL_NOZZLE_LEADER_LEN (/ tw 2.0)) (- y r SL_NOZZLE_LEADER_LEN) (- x r) (- y r))")
  o.w("          (list x (+ y r SL_NOZZLE_LEADER_LEN (/ tw 2.0)) x (+ y r))")
  o.w("          (list x (- y r SL_NOZZLE_LEADER_LEN (/ tw 2.0)) x (- y r))")
  o.w("        ))")
  o.w("        (setq found nil)")
  o.w("        (foreach cand candidates")
  o.w("          (if (not found)")
  o.w("            (progn")
  o.w("              (setq lx (nth 0 cand))")
  o.w("              (setq ly (nth 1 cand))")
  o.w("              (setq bb (SL_BBox lx ly tw th lr))")
  o.w("              (if (SL_ClearBBox bb) (setq found cand))")
  o.w("            )")
  o.w("          )")
  o.w("        )")
  o.w("        (if (not found) (setq found (car candidates)))")
  o.w("        (setq lx (nth 0 found))")
  o.w("        (setq ly (nth 1 found))")
  o.w("        (setq leaderStartX (nth 2 found))")
  o.w("        (setq leaderStartY (nth 3 found))")
  o.w("        (SL_Line leaderStartX leaderStartY lx ly layer)")
  o.w("        (SL_Text lx ly th lr txt layer)")
  o.w("        (setq bb (SL_BBox lx ly tw th lr))")
  o.w("        (SL_AddAvoidRect (nth 0 bb) (nth 1 bb) (- (nth 2 bb) (nth 0 bb)) (- (nth 3 bb) (nth 1 bb)))")
  o.w("      )")
  o.w("    )")
  o.w("  )")
  o.w("  ;; Register nozzle body after placing its label so the current circle does not block its own leader label.")
  o.w("  (SL_AddAvoidRect (- x r) (- y r) dia dia)")
  o.w(")")
  o.w("")
  o.w("(defun SL_Arrow (x1 y1 x2 y2 layer / dx dy len ux uy px py ah)")
  o.w("  ;; Draw line plus simple arrowhead.")
  o.w("  (setq ah SL_ARROW_HEAD)")
  o.w("  (setq dx (- x2 x1))")
  o.w("  (setq dy (- y2 y1))")
  o.w("  (setq len (sqrt (+ (* dx dx) (* dy dy))))")
  o.w("  (if (> len 0.0001)")
  o.w("    (progn")
  o.w("      (setq ux (/ dx len))")
  o.w("      (setq uy (/ dy len))")
  o.w("      (setq px (- uy))")
  o.w("      (setq py ux)")
  o.w("      (SL_Line x1 y1 x2 y2 layer)")
  o.w("      (SL_Line x2 y2 (- x2 (* ah ux) (* 0.55 ah px)) (- y2 (* ah uy) (* 0.55 ah py)) layer)")
  o.w("      (SL_Line x2 y2 (+ (- x2 (* ah ux)) (* 0.55 ah px)) (+ (- y2 (* ah uy)) (* 0.55 ah py)) layer)")
  o.w("    )")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_InchLabel (val)")
  o.w("  (strcat (rtos val 2 0) (chr 34))")
  o.w(")")
  o.w("")
  o.w("(defun SL_ReadableRot ()")
  o.w("  (cond")
  o.w("    ((= SL_ORIENTATION \"Vertical\") 0)")
  o.w("    ((= SL_ORIENTATION \"Horizontal CW\") 90)")
  o.w("    ((= SL_ORIENTATION \"Horizontal CCW\") -90)")
  o.w("    (T 0)")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_RulerTextRotX ()")
  o.w("  ;; Keeps X-axis ruler inch numbers and direction label readable after orientation transform.")
  o.w("  (cond")
  o.w("    ((= SL_ORIENTATION \"Vertical\") 0)")
  o.w("    ((= SL_ORIENTATION \"Horizontal CW\") 180)")
  o.w("    ((= SL_ORIENTATION \"Horizontal CCW\") 0)")
  o.w("    (T 0)")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_RulerTextRotY ()")
  o.w("  ;; Keeps Y-axis ruler inch numbers and direction label readable after orientation transform.")
  o.w("  (cond")
  o.w("    ((= SL_ORIENTATION \"Vertical\") 90)")
  o.w("    ((= SL_ORIENTATION \"Horizontal CW\") 90)")
  o.w("    ((= SL_ORIENTATION \"Horizontal CCW\") -90)")
  o.w("    (T 90)")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_LabelArrowLength (txt h fixedLen / calc)")
  o.w("  ;; Keep arrow about the length of the direction wording.")
  o.w("  (setq calc (* (strlen txt) h 0.60))")
  o.w("  (if (< calc 14.0) (setq calc 14.0))")
  o.w("  calc")
  o.w(")")
  o.w("")
  o.w("(defun SL_RulerX (x0 y0 length spacing layer label / pos tick arrLen mid last)")
  o.w("  (setq pos 0.0)")
  o.w("  (setq last -999.0)")
  o.w("  (setq tick 3.0)")
  o.w("  (SL_Line x0 y0 (+ x0 length) y0 layer)")
  o.w("  (while (<= pos length)")
  o.w("    (SL_Line (+ x0 pos) y0 (+ x0 pos) (- y0 tick) layer)")
  o.w("    (SL_Text (+ x0 pos) (- y0 5.0) 1.8 (SL_RulerTextRotX) (SL_InchLabel pos) layer)")
  o.w("    (setq last pos)")
  o.w("    (setq pos (+ pos spacing))")
  o.w("  )")
  o.w("  ;; Add final dimension tick if length does not land on the selected spacing.")
  o.w("  (if (> (- length last) 0.001)")
  o.w("    (progn")
  o.w("      (SL_Line (+ x0 length) y0 (+ x0 length) (- y0 tick) layer)")
  o.w("      (SL_Text (+ x0 length) (- y0 5.0) 1.8 (SL_RulerTextRotX) (SL_InchLabel length) layer)")
  o.w("    )")
  o.w("  )")
  o.w("  (setq arrLen (SL_LabelArrowLength label 2.5 0.0))")
  o.w("  (setq mid (/ length 2.0))")
  o.w("  (SL_Text (+ x0 mid) (- y0 10.0) 2.5 (SL_RulerTextRotX) label layer)")
  o.w("  (SL_Arrow (- (+ x0 mid) (/ arrLen 2.0)) (- y0 15.5) (+ (+ x0 mid) (/ arrLen 2.0)) (- y0 15.5) layer)")
  o.w(")")
  o.w("")
  o.w("(defun SL_RulerX_Top (x0 y0 length spacing layer label / pos tick arrLen mid last)")
  o.w("  ;; Visual top X ruler: ticks, inch numbers, label, and arrow stay above/outside the vessel.")
  o.w("  (setq pos 0.0)")
  o.w("  (setq last -999.0)")
  o.w("  (setq tick 3.0)")
  o.w("  (SL_Line x0 y0 (+ x0 length) y0 layer)")
  o.w("  (while (<= pos length)")
  o.w("    (SL_Line (+ x0 pos) y0 (+ x0 pos) (+ y0 tick) layer)")
  o.w("    (SL_Text (+ x0 pos) (+ y0 5.0) 1.8 (SL_RulerTextRotX) (SL_InchLabel pos) layer)")
  o.w("    (setq last pos)")
  o.w("    (setq pos (+ pos spacing))")
  o.w("  )")
  o.w("  (if (> (- length last) 0.001)")
  o.w("    (progn")
  o.w("      (SL_Line (+ x0 length) y0 (+ x0 length) (+ y0 tick) layer)")
  o.w("      (SL_Text (+ x0 length) (+ y0 5.0) 1.8 (SL_RulerTextRotX) (SL_InchLabel length) layer)")
  o.w("    )")
  o.w("  )")
  o.w("  (setq arrLen (SL_LabelArrowLength label 2.5 0.0))")
  o.w("  (setq mid (/ length 2.0))")
  o.w("  (SL_Text (+ x0 mid) (+ y0 10.0) 2.5 (SL_RulerTextRotX) label layer)")
  o.w("  (SL_Arrow (- (+ x0 mid) (/ arrLen 2.0)) (+ y0 15.5) (+ (+ x0 mid) (/ arrLen 2.0)) (+ y0 15.5) layer)")
  o.w(")")
  o.w("")
  o.w("(defun SL_RulerY (x0 y0 length spacing layer label / pos tick arrLen mid last)")
  o.w("  (setq pos 0.0)")
  o.w("  (setq last -999.0)")
  o.w("  (setq tick 3.0)")
  o.w("  (SL_Line x0 y0 x0 (+ y0 length) layer)")
  o.w("  (while (<= pos length)")
  o.w("    (SL_Line x0 (+ y0 pos) (- x0 tick) (+ y0 pos) layer)")
  o.w("    (SL_Text (- x0 5.5) (+ y0 pos) 1.8 (SL_RulerTextRotY) (SL_InchLabel pos) layer)")
  o.w("    (setq last pos)")
  o.w("    (setq pos (+ pos spacing))")
  o.w("  )")
  o.w("  ;; Add final dimension tick if length does not land on the selected spacing.")
  o.w("  (if (> (- length last) 0.001)")
  o.w("    (progn")
  o.w("      (SL_Line x0 (+ y0 length) (- x0 tick) (+ y0 length) layer)")
  o.w("      (SL_Text (- x0 5.5) (+ y0 length) 1.8 (SL_RulerTextRotY) (SL_InchLabel length) layer)")
  o.w("    )")
  o.w("  )")
  o.w("  (setq arrLen (SL_LabelArrowLength label 2.5 0.0))")
  o.w("  (setq mid (/ length 2.0))")
  o.w("  (SL_Text (- x0 11.0) (+ y0 mid) 2.5 (SL_RulerTextRotY) label layer)")
  o.w("  (SL_Arrow (- x0 16.5) (- (+ y0 mid) (/ arrLen 2.0)) (- x0 16.5) (+ (+ y0 mid) (/ arrLen 2.0)) layer)")
  o.w(")")
  o.w("")
  o.w("(defun SL_RulerY_Right (x0 y0 length spacing layer label / pos tick arrLen mid last)")
  o.w("  ;; Visual right Y ruler: ticks, inch numbers, label, and arrow stay right/outside the vessel.")
  o.w("  (setq pos 0.0)")
  o.w("  (setq last -999.0)")
  o.w("  (setq tick 3.0)")
  o.w("  (SL_Line x0 y0 x0 (+ y0 length) layer)")
  o.w("  (while (<= pos length)")
  o.w("    (SL_Line x0 (+ y0 pos) (+ x0 tick) (+ y0 pos) layer)")
  o.w("    (SL_Text (+ x0 5.5) (+ y0 pos) 1.8 (SL_RulerTextRotY) (SL_InchLabel pos) layer)")
  o.w("    (setq last pos)")
  o.w("    (setq pos (+ pos spacing))")
  o.w("  )")
  o.w("  (if (> (- length last) 0.001)")
  o.w("    (progn")
  o.w("      (SL_Line x0 (+ y0 length) (+ x0 tick) (+ y0 length) layer)")
  o.w("      (SL_Text (+ x0 5.5) (+ y0 length) 1.8 (SL_RulerTextRotY) (SL_InchLabel length) layer)")
  o.w("    )")
  o.w("  )")
  o.w("  (setq arrLen (SL_LabelArrowLength label 2.5 0.0))")
  o.w("  (setq mid (/ length 2.0))")
  o.w("  (SL_Text (+ x0 11.0) (+ y0 mid) 2.5 (SL_RulerTextRotY) label layer)")
  o.w("  (SL_Arrow (+ x0 16.5) (- (+ y0 mid) (/ arrLen 2.0)) (+ x0 16.5) (+ (+ y0 mid) (/ arrLen 2.0)) layer)")
  o.w(")")
  o.w("")
