  o.w(";; v4.4.3 dedicated Horizontal CW visual ruler functions.")
  o.w(";; These keep Vertical behavior untouched while mirroring CW visual bottom/left rulers correctly.")
  o.w("(defun SL_RulerX_CW_Left (x0 y0 length spacing layer label / pos tick arrLen mid last)")
  o.w("  ;; Logical X ruler becomes the visual left ruler in Horizontal CW.")
  o.w("  ;; Tick marks are flipped toward the vessel; text stays outside and readable.")
  o.w("  (setq pos 0.0)")
  o.w("  (setq last -999.0)")
  o.w("  (setq tick 3.0)")
  o.w("  (SL_Line x0 y0 (+ x0 length) y0 layer)")
  o.w("  (while (<= pos length)")
  o.w("    (SL_Line (+ x0 pos) y0 (+ x0 pos) (- y0 tick) layer)")
  o.w("    (SL_Text (+ x0 pos) (- y0 5.0) 1.8 (SL_RulerTextRotX) (SL_InchLabel pos) layer)")
  o.w("    (setq last pos)")
  o.w("    (setq pos (+ pos spacing))")
  o.w("  )")
  o.w("  (if (> (- length last) 0.001)")
  o.w("    (progn")
  o.w("      (SL_Line (+ x0 length) y0 (+ x0 length) (- y0 tick) layer)")
  o.w("      (SL_Text (+ x0 length) (- y0 5.0) 1.8 (SL_RulerTextRotX) (SL_InchLabel length) layer)")
  o.w("    )")
  o.w("  )")
  o.w("  (setq arrLen (SL_LabelArrowLength label 2.5 0.0))")
  o.w("  (setq mid (/ length 2.0))")
  o.w("  (SL_Text (+ x0 mid) (- y0 10.0) 2.5 (SL_RulerTextRotX) label layer)")
  o.w("  (SL_Arrow (- (+ x0 mid) (/ arrLen 2.0)) (- y0 15.5) (+ (+ x0 mid) (/ arrLen 2.0)) (- y0 15.5) layer)")
  o.w(")")
  o.w("")
  o.w("(defun SL_RulerY_CW_Bottom (x0 y0 length spacing layer label / pos tick arrLen mid last)")
  o.w("  ;; Logical Y ruler is placed at vesselXLen + rulerOffset so it becomes the visual bottom ruler in Horizontal CW.")
  o.w("  ;; Ticks point toward vessel; numbers, direction label, and arrow stay below/outside the ruler.")
  o.w("  (setq pos 0.0)")
  o.w("  (setq last -999.0)")
  o.w("  (setq tick 3.0)")
  o.w("  (SL_Line x0 y0 x0 (+ y0 length) layer)")
  o.w("  (while (<= pos length)")
  o.w("    (SL_Line x0 (+ y0 pos) (+ x0 tick) (+ y0 pos) layer)")
  o.w("    (SL_Text (+ x0 5.5) (+ y0 pos) 1.8 (SL_RulerTextRotY) (SL_InchLabel pos) layer)")
  o.w("    (setq last pos)")
  o.w("    (setq pos (+ pos spacing))")
  o.w("  )")
  o.w("  (if (> (- length last) 0.001)")
  o.w("    (progn")
  o.w("      (SL_Line x0 (+ y0 length) (+ x0 tick) (+ y0 length) layer)")
  o.w("      (SL_Text (+ x0 5.5) (+ y0 length) 1.8 (SL_RulerTextRotY) (SL_InchLabel length) layer)")
  o.w("    )")
  o.w("  )")
  o.w("  (setq arrLen (SL_LabelArrowLength label 2.5 0.0))")
  o.w("  (setq mid (/ length 2.0))")
  o.w("  (SL_Text (+ x0 11.0) (+ y0 mid) 2.5 (SL_RulerTextRotY) label layer)")
  o.w("  (SL_Arrow (+ x0 16.5) (- (+ y0 mid) (/ arrLen 2.0)) (+ x0 16.5) (+ (+ y0 mid) (/ arrLen 2.0)) layer)")
  o.w(")")
  o.w("")
  o.w(";; v4.4.8 dedicated Horizontal CCW visual ruler functions.")
  o.w(";; CCW mapping: logical X controls visual LEFT/RIGHT; logical Y controls visual TOP/BOTTOM.")
  o.w("(defun SL_RulerX_CCW_Left (x0 y0 length spacing layer label / pos tick arrLen mid last)")
