  o.w("  (SL_Text (+ x0 mid) (+ y0 10.0) 2.5 (SL_RulerTextRotX) label layer)")
  o.w("  (SL_Arrow (- (+ x0 mid) (/ arrLen 2.0)) (+ y0 15.5) (+ (+ x0 mid) (/ arrLen 2.0)) (+ y0 15.5) layer)")
  o.w(")")
  o.w("")
  o.w("(defun SL_RulerY_CCW_Bottom (x0 y0 length spacing layer label / pos tick arrLen mid last)")
  o.w("  ;; Logical Y ruler at x = -offset becomes the visual bottom ruler in Horizontal CCW.")
