  o.w("                (SL_PaperSectionReferences vpLeft vpBottom vpW vpH)")
  o.w("                ;; Keep the panel clear of the right-side reference labels and")
  o.w("                ;; align the bottom of its legend summary with the section bottom.")
  o.w("                (setq infoX (+ left (* areaW 0.865)) infoTop (+ vpBottom (* 2.55 paperUnit)))")
  o.w("                (SL_PaperSectionInfo infoX infoTop paperUnit)")
  o.w("                (setq i (1+ i))")
  o.w("              )")
  o.w("              (if firstSheet (SL_ActivateSheet firstSheet))")
  o.w("              (setvar \"CMDECHO\" oldCmdecho)")
