/** From WriteOverlayLispFunctions, SLG_Utilities.bas lines 5290-5347. */
export function WriteOverlayLispFunctions(o: LibraryContext): void {
  if (o.acad) {
    o.w(";;; AutoCAD overlay image insertion helpers - validated exact-fit workflow")
    o.w("(defun SL_ImageBounds (ent / obj pmin pmax err)")
    o.w("  (vl-load-com) (setq obj (vlax-ename->vla-object ent))")
    o.w("  (setq err (vl-catch-all-apply 'vla-GetBoundingBox (list obj 'pmin 'pmax)))")
    o.w("  (if (vl-catch-all-error-p err) nil (list (vlax-safearray->list pmin) (vlax-safearray->list pmax)))")
    o.w(")")
    o.w("(defun SL_InsertFitImage (x y w h img / rot target ent b mn mx bw bh factor)")
    o.w("  (SL_SetLayer \"SCAN_IMAGES\")")
    o.w("  (cond")
    o.w("    ((= SL_ORIENTATION \"Vertical\") (setq rot 0.0 target (list x y 0.0)))")
    o.w("    ((= SL_ORIENTATION \"Horizontal CCW\") (setq rot 90.0 target (list (- (+ y h)) x 0.0)))")
    o.w("    (T (setq rot -90.0 target (list y (- (+ x w)) 0.0)))")
    o.w("  )")
    o.w("  (command \"_.-IMAGE\" \"_Attach\" img '(0.0 0.0 0.0) 1.0 rot)")
    o.w("  (setq ent (entlast) b (SL_ImageBounds ent) mn (car b) mx (cadr b) bw (- (car mx) (car mn)) bh (- (cadr mx) (cadr mn)))")
    o.w("  (setq factor (if (< (abs rot) 0.0001) (/ w bw) (/ w bh)))")
    o.w("  (command \"_.SCALE\" ent \"\" '(0.0 0.0 0.0) factor)")
    o.w("  (setq b (SL_ImageBounds ent) mn (car b))")
    o.w("  (command \"_.MOVE\" ent \"\" mn target)")
    o.w(")")
    o.w("")
    return
  }
  o.w(";;; Overlay image insertion helpers")
  o.w("(defun SL_OverlayLL (x y w h / p)")
  o.w("  ;; Lower-left insertion point after coordinate transform.")
  o.w("  (cond")
  o.w("    ((= SL_ORIENTATION \"Vertical\") (SL_pt (SL_tf_x x y) (SL_tf_y x y)))")
  o.w("    ((= SL_ORIENTATION \"Horizontal CW\") (SL_pt (SL_tf_x (+ x w) y) (SL_tf_y (+ x w) y)))")
  o.w("    ((= SL_ORIENTATION \"Horizontal CCW\") (SL_pt (SL_tf_x x (+ y h)) (SL_tf_y x (+ y h))))")
  o.w("    (T (SL_pt (SL_tf_x x y) (SL_tf_y x y)))")
  o.w("  )")
  o.w(")")
  o.w("")
  o.w("(defun SL_InsertFitImage (x y w h img / ins sc rot)")
  o.w("  (SL_SetLayer \"SCAN_IMAGES\")")
  o.w("  ;; v3.0B.20 TEST: CCW overlay insert/rotation added.")
  o.w("  ;; Confirmed working: Vertical = x,y rot 0; Horizontal CW = y,-x rot -90; sc = w.")
  o.w("  ;; CCW test: insertion = -y,x; rot = 90; sc = w.")
  o.w("  (setq sc w)")
  o.w("  (cond")
  o.w("    ((= SL_ORIENTATION \"Vertical\")")
  o.w("      (setq ins (strcat (rtos x 2 4) \",\" (rtos y 2 4)))")
  o.w("      (setq rot \"0\")")
  o.w("    )")
  o.w("    ((= SL_ORIENTATION \"Horizontal CCW\")")
  o.w("      (setq ins (strcat (rtos (- y) 2 4) \",\" (rtos x 2 4)))")
  o.w("      (setq rot \"90\")")
  o.w("    )")
  o.w("    (T")
  o.w("      (setq ins (strcat (rtos y 2 4) \",\" (rtos (- x) 2 4)))")
  o.w("      (setq rot \"-90\")")
  o.w("    )")
  o.w("  )")
  o.w("  (command \"EDITIMAGE\" \"Attach\" img ins (rtos sc 2 8) rot)")
  o.w(")")
  o.w("")
}

