/** From ExportAxisBuilderLSP (part), SLG_Utilities.bas lines 4685-4850. */
export function WriteCommandsTail(o: LibraryContext): void {
  o.w("(defun c:AXISDRAWING () (c:SCANOVERLAY))")
  o.w("")
  o.w(";; Layer visibility controls for the one-drawing AxisBuilder workflow.")
  o.w("(defun SL_LayerOn (name) (command \"_.-LAYER\" \"_On\" name \"\"))")
  o.w("(defun SL_LayerOff (name) (command \"_.-LAYER\" \"_Off\" name \"\"))")
  o.w("(defun SL_LayoutView ()")
  o.w("  (SL_SetLayer \"0\")")
  o.w("  (SL_LayerOff \"SCAN_IMAGES\")")
  o.w("  (SL_LayerOn \"SCANS\")")
  o.w("  (SL_LayerOn \"SCAN_TEXT\")")
  o.w("  (SL_LayerOn \"AUT_HATCH\")")
  o.w("  (setvar \"IMAGEFRAME\" 0)")
  o.w("  (command \"_.REGEN\")")
  o.w("  (princ \"\\nAxisBuilder Layout View active.\")")
  o.w("  (princ)")
  o.w(")")
  o.w("(defun c:ABLAYOUT () (SL_LayoutView))")
  o.w("")
  o.w("(defun SL_OverlayView ()")
  o.w("  (SL_SetLayer \"0\")")
  o.w("  (SL_LayerOn \"SCAN_IMAGES\")")
  o.w("  (SL_LayerOff \"AUT_HATCH\")")
  o.w("  (SL_LayerOff \"SCAN_TEXT\")")
  o.w("  (SL_LayerOff \"SCANS\")")
  o.w("  (setvar \"IMAGEFRAME\" " + CStr(o.overlayImageFrame) + ")")
  o.w("  (command \"_.REGEN\")")
  o.w("  (princ \"\\nAxisBuilder Overlay View active.\")")
  o.w("  (princ)")
  o.w(")")
  o.w("(defun c:ABOVERLAY () (SL_OverlayView))")
  o.w("")
  o.w(";; Grouped visibility controls. Each group uses the first existing layer")
  o.w(";; as its state and then turns the complete group on or off together.")
  o.w("(defun SL_LayerExists (name) (if (tblsearch \"LAYER\" name) T nil))")
  o.w("(defun SL_LayerIsOn (name / data color)")
  o.w("  (setq data (tblsearch \"LAYER\" name))")
  o.w("  (if data")
  o.w("    (progn (setq color (cdr (assoc 62 data))) (or (null color) (> color 0)))")
  o.w("    nil")
  o.w("  )")
  o.w(")")
  o.w("(defun SL_FirstExistingLayer (layers / found)")
  o.w("  (setq found nil)")
  o.w("  (while (and layers (null found))")
  o.w("    (if (SL_LayerExists (car layers)) (setq found (car layers)))")
  o.w("    (setq layers (cdr layers))")
  o.w("  )")
  o.w("  found")
  o.w(")")
  o.w("(defun SL_SetLayerGroup (layers turnOn / layerName)")
  o.w("  (SL_SetLayer \"0\")")
  o.w("  (foreach layerName layers")
  o.w("    (if (SL_LayerExists layerName)")
  o.w("      (if turnOn (SL_LayerOn layerName) (SL_LayerOff layerName))")
  o.w("    )")
  o.w("  )")
  o.w("  (command \"_.REGEN\")")
  o.w(")")
  o.w("(defun SL_ToggleLayerGroup (label layers / stateLayer turnOn)")
  o.w("  (setq stateLayer (SL_FirstExistingLayer layers))")
  o.w("  (if stateLayer")
  o.w("    (progn")
  o.w("      (setq turnOn (not (SL_LayerIsOn stateLayer)))")
  o.w("      (SL_SetLayerGroup layers turnOn)")
  o.w("      (princ (strcat \"\\n\" label (if turnOn \" shown.\" \" hidden.\")))")
  o.w("    )")
  o.w("    (princ (strcat \"\\nNo \" label \" layers exist in this drawing.\"))")
  o.w("  )")
  o.w("  (princ)")
  o.w(")")
  o.w("")
  o.w("(defun c:ABIMAGES () (SL_ToggleLayerGroup \"Scan images\" '(\"SCAN_IMAGES\")))")
  o.w("(defun c:ABSCANS () (SL_ToggleLayerGroup \"Scan outlines and labels\" '(\"SCANS\" \"SCAN_TEXT\")))")
  o.w("(defun c:ABHATCH () (SL_ToggleLayerGroup \"Scan hatching\" '(\"AUT_HATCH\")))")
  o.w("(defun c:ABWELDS () (SL_ToggleLayerGroup \"Welds and weld labels\" '(\"CIRC_WELDS\" \"LONG_SEAMS\" \"CIRC_WELD_TEXT\" \"LONG_SEAM_TEXT\")))")
  o.w("(defun c:ABNOZZLES () (SL_ToggleLayerGroup \"Shell nozzles\" '(\"NOZZLES\" \"SHELL_NOZZLE_TEXT\")))")
  o.w("(defun c:ABOBJECTS () (SL_ToggleLayerGroup \"Supports and objects\" '(\"SUPPORTS\" \"SUPPORT_TEXT\")))")
  o.w("(defun c:ABRULERS () (SL_ToggleLayerGroup \"Rulers and references\" '(\"X_AXIS\" \"Y_AXIS\" \"X_RULER_TEXT\" \"Y_RULER_TEXT\")))")
  o.w("(defun c:ABHEADS () (SL_ToggleLayerGroup \"Head views\" '(\"HEADS\" \"HEAD_NOZZLE_TEXT\" \"HEAD_MUT_TEXT\" \"HEAD_TITLE_TEXT\" \"HEAD_CLOCK_TEXT\")))")
  o.w("(defun c:ABINFO () (SL_ToggleLayerGroup \"Legend and title block\" '(\"LEGEND\" \"LEGEND_SAMPLE\" \"LEGEND_AUT_HATCH\" \"LEGEND_MUT_HATCH\" \"LEGEND_TEXT\" \"TITLE_BLOCK\" \"TITLE_BLOCK_TEXT\")))")
  o.w("")
  o.w("(defun SL_VisibilityMenuDisplay ()")
  o.w("  (princ \"\\n----------------------------------------\")")
  o.w("  (princ \"\\n       AXISBUILDER VISIBILITY CONTROLS\")")
  o.w("  (princ \"\\n----------------------------------------\")")
  o.w("  (princ \"\\n  1  Show/Hide Scan Images\")")
  o.w("  (princ \"\\n  2  Show/Hide Scan Outlines and Labels\")")
  o.w("  (princ \"\\n  3  Show/Hide Scan Hatching\")")
  o.w("  (princ \"\\n  4  Show/Hide Welds and Weld Labels\")")
  o.w("  (princ \"\\n  5  Show/Hide Shell Nozzles\")")
  o.w("  (princ \"\\n  6  Show/Hide Supports and Objects\")")
  o.w("  (princ \"\\n  7  Show/Hide Rulers and References\")")
  o.w("  (princ \"\\n  8  Show/Hide Head Views\")")
  o.w("  (princ \"\\n  9  Show/Hide Legend and Title Block\")")
  o.w("  (princ \"\\n  0  Back to Main Menu\")")
  o.w(")")
  o.w("(defun c:ABVISIBILITY ( / choice done)")
  o.w("  (setq done nil)")
  o.w("  (while (not done)")
  o.w("    (SL_VisibilityMenuDisplay)")
  o.w("    (initget 4)")
  o.w("    (setq choice (getint \"\\nSelect visibility option [0-9] <0>: \"))")
  o.w("    (if (null choice) (setq choice 0))")
  o.w("    (cond")
  o.w("      ((= choice 0) (setq done T))")
  o.w("      ((= choice 1) (c:ABIMAGES))")
  o.w("      ((= choice 2) (c:ABSCANS))")
  o.w("      ((= choice 3) (c:ABHATCH))")
  o.w("      ((= choice 4) (c:ABWELDS))")
  o.w("      ((= choice 5) (c:ABNOZZLES))")
  o.w("      ((= choice 6) (c:ABOBJECTS))")
  o.w("      ((= choice 7) (c:ABRULERS))")
  o.w("      ((= choice 8) (c:ABHEADS))")
  o.w("      ((= choice 9) (c:ABINFO))")
  o.w("      (T (princ \"\\nInvalid option. Enter a number from 0 through 9.\"))")
  o.w("    )")
  o.w("  )")
  o.w("  (princ)")
  o.w(")")
  o.w("")
  o.w(";; One-drawing AXISBUILDER launcher.")
  o.w("(defun SL_ScanMenuDisplay ()")
  o.w("  (princ \"\\n========================================\")")
  o.w("  (princ \"\\n              AXISBUILDER\")")
  o.w("  (princ \"\\n========================================\")")
  o.w("  (princ \"\\n  1  Generate Master Drawing\")")
  o.w("  (princ \"\\n  2  Layout View\")")
  o.w("  (princ \"\\n  3  Overlay View\")")
  o.w("  (princ \"\\n  4  Visibility Controls\")")
  o.w("  (princ \"\\n  5  Resize Generated Text\")")
  o.w("  (princ \"\\n  6  Wrap Shell Nozzle\")")
  o.w("  (princ \"\\n  7  Wrap Support/Object\")")
  o.w("  (princ \"\\n  8  Create Letter-Size Section Sheets\")")
  o.w("  (princ \"\\n  0  Exit\")")
  o.w(")")
  o.w("")
  o.w("(defun c:AXISBUILDER ( / choice done)")
  o.w("  (setq done nil)")
  o.w("  (while (not done)")
  o.w("    (SL_ScanMenuDisplay)")
  o.w("    (initget 4)")
  o.w("    (setq choice (getint \"\\nSelect command [0-8] <0>: \"))")
  o.w("    (if (null choice) (setq choice 0))")
  o.w("    (cond")
  o.w("      ((= choice 0) (setq done T))")
  o.w("      ((= choice 1) (SL_RunMenuCommand 'c:AXISDRAWING \"AXISDRAWING\"))")
  o.w("      ((= choice 2) (SL_RunMenuCommand 'c:ABLAYOUT \"ABLAYOUT\"))")
  o.w("      ((= choice 3) (SL_RunMenuCommand 'c:ABOVERLAY \"ABOVERLAY\"))")
  o.w("      ((= choice 4) (SL_RunMenuCommand 'c:ABVISIBILITY \"ABVISIBILITY\"))")
  o.w("      ((= choice 5) (SL_RunMenuCommand 'c:TEXTRESIZE \"TEXTRESIZE\"))")
  o.w("      ((= choice 6) (SL_RunMenuCommand 'c:NOZZLEWRAP \"NOZZLEWRAP\"))")
  o.w("      ((= choice 7) (SL_RunMenuCommand 'c:OBJECTWRAP \"OBJECTWRAP\"))")
  o.w("      ((= choice 8) (SL_RunMenuCommand 'c:SECTIONPAGES \"SECTIONPAGES\"))")
  o.w("      (T (princ \"\\nInvalid option. Enter a number from 0 through 8.\"))")
  o.w("    )")
  o.w("  )")
  o.w("  (princ \"\\nAXISBUILDER closed.\")")
  o.w("  (princ)")
  o.w(")")
  o.w("")
  o.w(";; Backward-compatible alias for existing workflows.")
  o.w("(defun c:SCANMENU () (c:AXISBUILDER))")
  o.w("")
  o.w("(princ \"\\nAxisBuilder v5.0 master drawing loaded. Type AXISBUILDER, or AXISDRAWING to generate directly.\")")
  o.w("(princ)")
}
